// Command swagger-combine builds the monolith-style combined Swagger bundle
// from the three per-service specs generated by `swag init`.
//
// It merges the three specs into one (paths + definitions union, verified
// conflict-free), splits the combined spec per business module using the same
// tag->module mapping the monolith used, copies each per-service spec, and
// writes the original Swagger UI page (plus an extra "Service" selector).
//
// Output bundle (served by the Account service at /swagger + /api-docs):
//
//	services/account/api/swagger/combined/
//	├── index.html
//	├── swagger.json                # all services combined
//	├── services/<svc>/swagger.json
//	└── modules/<module>/swagger.json
//
// Run `make swagger-combine` (also part of `make generate`).
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
)

var serviceOrder = []string{"account", "commerce", "ai"}

var swaggerFiles = map[string]string{
	"account":  "services/account/api/swagger/swagger.json",
	"commerce": "services/commerce/api/swagger/swagger.json",
	"ai":       "services/ai/api/swagger/swagger.json",
}

func main() {
	root := flag.String("root", ".", "repository root")
	out := flag.String("out", "services/account/api/swagger/combined", "bundle output directory (relative to root)")
	mapping := flag.String("mapping", "shared/tools/swagger-combine/module-mapping.json", "tag->module mapping (relative to root)")
	flag.Parse()

	if err := run(*root, *out, *mapping); err != nil {
		fmt.Fprintln(os.Stderr, "swagger-combine:", err)
		os.Exit(1)
	}
}

func run(root, outRel, mappingRel string) error {
	docs := map[string]map[string]any{}
	for _, svc := range serviceOrder {
		raw, err := os.ReadFile(filepath.Join(root, swaggerFiles[svc]))
		if err != nil {
			return fmt.Errorf("read %s spec: %w", svc, err)
		}
		var doc map[string]any
		if err := json.Unmarshal(raw, &doc); err != nil {
			return fmt.Errorf("parse %s spec: %w", svc, err)
		}
		docs[svc] = doc
	}

	tagModule, err := loadMapping(filepath.Join(root, mappingRel))
	if err != nil {
		return err
	}

	combined, err := mergeDocs(docs)
	if err != nil {
		return err
	}

	// pathService lets us attribute each module to its owning service.
	pathService := map[string]string{}
	for _, svc := range serviceOrder {
		for path := range asMap(docs[svc]["paths"]) {
			pathService[path] = svc
		}
	}

	combinedPaths := asMap(combined["paths"])
	modulePaths := map[string]map[string]any{}
	moduleService := map[string]string{}
	for path, ops := range combinedPaths {
		module, err := moduleForPath(asMap(ops), tagModule)
		if err != nil {
			return fmt.Errorf("path %s: %w", path, err)
		}
		if module == "" {
			return fmt.Errorf("path %s cannot be mapped to any module (missing tag mapping)", path)
		}
		if modulePaths[module] == nil {
			modulePaths[module] = map[string]any{}
		}
		modulePaths[module][path] = ops
		if prev, ok := moduleService[module]; ok && prev != pathService[path] {
			return fmt.Errorf("module %s spans services %s and %s", module, prev, pathService[path])
		}
		moduleService[module] = pathService[path]
	}

	outDir := filepath.Join(root, outRel)
	if err := os.MkdirAll(outDir, 0o755); err != nil {
		return fmt.Errorf("create output dir: %w", err)
	}

	if err := writeJSON(filepath.Join(outDir, "swagger.json"), combined); err != nil {
		return err
	}
	for _, svc := range serviceOrder {
		if err := writeJSON(filepath.Join(outDir, "services", svc, "swagger.json"), docs[svc]); err != nil {
			return err
		}
	}

	modules := make([]string, 0, len(modulePaths))
	for m := range modulePaths {
		modules = append(modules, m)
	}
	sort.Strings(modules)

	for _, module := range modules {
		moduleDoc := shallowCopy(combined)
		moduleDoc["paths"] = modulePaths[module]
		moduleDoc["tags"] = filterTags(asSlice(combined["tags"]), tagModule, module)
		if err := writeJSON(filepath.Join(outDir, "modules", module, "swagger.json"), moduleDoc); err != nil {
			return err
		}
	}

	html, err := renderHTML(combinedCatalog(moduleService, modules))
	if err != nil {
		return err
	}
	if err := os.WriteFile(filepath.Join(outDir, "index.html"), []byte(html), 0o644); err != nil {
		return fmt.Errorf("write index.html: %w", err)
	}

	// Every service also gets an old-look UI for its own port (/swagger), backed
	// by its own spec only (the combined UI lives in the Account bundle).
	for _, svc := range serviceOrder {
		svcHTML, err := renderHTML(serviceCatalog(svc, serviceModules(svc, moduleService, modules)))
		if err != nil {
			return err
		}
		indexPath := filepath.Join(root, "services", svc, "api", "swagger", "index.html")
		if err := os.WriteFile(indexPath, []byte(svcHTML), 0o644); err != nil {
			return fmt.Errorf("write %s index.html: %w", svc, err)
		}
	}

	fmt.Printf("swagger-combine: bundle written to %s (%d services, %d modules)\n", outRel, len(serviceOrder), len(modules))
	return nil
}

func serviceModules(svc string, moduleService map[string]string, modules []string) []string {
	var out []string
	for _, module := range modules {
		if moduleService[module] == svc {
			out = append(out, module)
		}
	}
	sort.Strings(out)
	return out
}

func combinedCatalog(moduleService map[string]string, modules []string) map[string]any {
	moduleURLs := map[string]string{}
	for _, module := range modules {
		moduleURLs[module] = "/api-docs/modules/" + module + "/swagger.json"
	}
	services := map[string]any{}
	for _, svc := range serviceOrder {
		services[svc] = map[string]any{
			"url":     "/api-docs/services/" + svc + "/swagger.json",
			"modules": serviceModules(svc, moduleService, modules),
		}
	}
	return map[string]any{
		"allUrl":        "/api-docs/swagger.json",
		"services":      services,
		"modules":       moduleURLs,
		"moduleService": moduleService,
	}
}

func serviceCatalog(svc string, modules []string) map[string]any {
	return map[string]any{
		"allUrl": "/api-docs/swagger.json",
		"services": map[string]any{
			svc: map[string]any{
				"url":     "/api-docs/swagger.json",
				"modules": modules,
			},
		},
		"modules":       map[string]string{},
		"moduleService": map[string]string{},
	}
}

// mergeDocs unions the per-service specs. Definition/security collisions are
// allowed only when the JSON is identical (shared generated DTOs).
func mergeDocs(docs map[string]map[string]any) (map[string]any, error) {
	combined := map[string]any{}
	for k, v := range docs[serviceOrder[0]] {
		combined[k] = v
	}

	paths := map[string]any{}
	defs := map[string]any{}
	secDefs := map[string]any{}
	tags := map[string]any{}

	for _, svc := range serviceOrder {
		doc := docs[svc]
		for path, ops := range asMap(doc["paths"]) {
			if _, exists := paths[path]; exists {
				return nil, fmt.Errorf("duplicate path across services: %s", path)
			}
			paths[path] = ops
		}
		if err := unionUnique(defs, asMap(doc["definitions"]), "definition"); err != nil {
			return nil, err
		}
		if err := unionUnique(secDefs, asMap(doc["securityDefinitions"]), "securityDefinition"); err != nil {
			return nil, err
		}
		for _, tag := range asSlice(doc["tags"]) {
			if name, ok := asMap(tag)["name"].(string); ok {
				if _, exists := tags[name]; !exists {
					tags[name] = tag
				}
			}
		}
	}

	combined["paths"] = paths
	combined["definitions"] = defs
	combined["securityDefinitions"] = secDefs
	combined["tags"] = sortedTags(tags)
	combined["info"] = map[string]any{
		"title":       "SmartWardrobe Backend API",
		"description": "Combined API docs for the Account, Commerce and AI services.",
		"version":     "1.0",
	}
	return combined, nil
}

func unionUnique(dst, src map[string]any, kind string) error {
	for name, value := range src {
		if existing, ok := dst[name]; ok {
			if !reflect.DeepEqual(existing, value) {
				return fmt.Errorf("%s %q differs between services and cannot be merged", kind, name)
			}
			continue
		}
		dst[name] = value
	}
	return nil
}

func sortedTags(tags map[string]any) []any {
	names := make([]string, 0, len(tags))
	for name := range tags {
		names = append(names, name)
	}
	sort.Strings(names)
	out := make([]any, 0, len(names))
	for _, name := range names {
		out = append(out, tags[name])
	}
	return out
}

// moduleForPath returns the module owning every tagged operation of a path.
func moduleForPath(ops map[string]any, tagModule map[string]string) (string, error) {
	module := ""
	assigned := false
	for _, raw := range ops {
		op, ok := raw.(map[string]any)
		if !ok {
			continue
		}
		for _, tag := range asSlice(op["tags"]) {
			name, _ := tag.(string)
			m, exists := tagModule[name]
			if !exists {
				return "", fmt.Errorf("tag %q missing from mapping", name)
			}
			if assigned && m != module {
				return "", fmt.Errorf("operations span modules %s and %s", module, m)
			}
			module, assigned = m, true
		}
	}
	return module, nil
}

func filterTags(all []any, tagModule map[string]string, module string) []any {
	out := []any{}
	for _, tag := range all {
		if name, ok := asMap(tag)["name"].(string); ok && tagModule[name] == module {
			out = append(out, tag)
		}
	}
	return out
}

func shallowCopy(m map[string]any) map[string]any {
	out := make(map[string]any, len(m))
	for k, v := range m {
		out[k] = v
	}
	return out
}

func writeJSON(path string, value any) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("create dir for %s: %w", path, err)
	}
	data, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal %s: %w", path, err)
	}
	if err := os.WriteFile(path, append(data, '\n'), 0o644); err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	return nil
}

func loadMapping(path string) (map[string]string, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read mapping: %w", err)
	}
	var moduleTags map[string][]string
	if err := json.Unmarshal(raw, &moduleTags); err != nil {
		return nil, fmt.Errorf("parse mapping: %w", err)
	}
	tagModule := map[string]string{}
	for module, tags := range moduleTags {
		for _, tag := range tags {
			if prev, ok := tagModule[tag]; ok && prev != module {
				return nil, fmt.Errorf("tag %q belongs to modules %s and %s", tag, prev, module)
			}
			tagModule[tag] = module
		}
	}
	return tagModule, nil
}

func asMap(v any) map[string]any {
	m, _ := v.(map[string]any)
	return m
}

func asSlice(v any) []any {
	s, _ := v.([]any)
	return s
}

func renderHTML(catalog map[string]any) (string, error) {
	data, err := json.Marshal(catalog)
	if err != nil {
		return "", fmt.Errorf("marshal catalog: %w", err)
	}
	return strings.Replace(indexHTML, "__CATALOG_JSON__", string(data), 1), nil
}

const indexHTML = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <meta name="color-scheme" content="light" />
    <title>SmartWardrobe BE - Swagger UI</title>
    <link rel="stylesheet" href="https://unpkg.com/swagger-ui-dist@5/swagger-ui.css" />
    <style>
      :root { color-scheme: light !important; }
      .custom-toolbar {
        background-color: #fafafa;
        padding: 10px 20px;
        border-bottom: 1px solid #e8e8e8;
        display: flex;
        justify-content: flex-end;
        align-items: center;
        gap: 10px;
        font-family: sans-serif;
        flex-wrap: wrap;
      }
      .toolbar-group { display: flex; align-items: center; gap: 6px; }
      .toolbar-label { font-size: 14px; color: #555; }
      .custom-select {
        padding: 6px 10px;
        border: 1px solid #ccc;
        background: #fff;
        border-radius: 4px;
        font-size: 14px;
        color: #333;
        cursor: pointer;
      }
      .custom-btn {
        padding: 6px 12px;
        border: 1px solid #ccc;
        background: #fff;
        border-radius: 4px;
        cursor: pointer;
        font-size: 14px;
        font-weight: 600;
        transition: all 0.2s;
      }
      .custom-btn:hover { background: #eee; }
      .custom-btn.primary { background: #49cc90; color: #fff; border-color: #49cc90; }
      .custom-btn.primary:hover { background: #3b9c6f; }
      @media print { .custom-toolbar { display: none; } }
    </style>
  </head>
  <body>
    <div class="custom-toolbar">
      <div class="toolbar-group">
        <span class="toolbar-label">API Version:</span>
        <select id="version-select" class="custom-select"></select>
      </div>
      <div class="toolbar-group">
        <span class="toolbar-label">Service:</span>
        <select id="service-select" class="custom-select"></select>
      </div>
      <div class="toolbar-group">
        <span class="toolbar-label">Module:</span>
        <select id="module-select" class="custom-select"></select>
      </div>
      <button class="custom-btn primary" onclick="expandAll()">Mở rộng tất cả (Expand All)</button>
      <button class="custom-btn" onclick="collapseAll()">Thu gọn tất cả (Collapse All)</button>
    </div>

    <div id="swagger-ui"></div>

    <script src="https://unpkg.com/swagger-ui-dist@5/swagger-ui-bundle.js"></script>
    <script src="https://unpkg.com/swagger-ui-dist@5/swagger-ui-standalone-preset.js"></script>
    <script>
      // Force light mode by default.
      if (window.matchMedia) {
        const originalMatchMedia = window.matchMedia;
        window.matchMedia = function (query) {
          if (query && query.includes("prefers-color-scheme: dark")) {
            return {
              matches: false,
              media: query,
              onchange: null,
              addListener: function () {},
              removeListener: function () {},
              addEventListener: function () {},
              removeEventListener: function () {},
            };
          }
          return originalMatchMedia(query);
        };
      }

      const CATALOG = __CATALOG_JSON__;
      const API_VERSIONS = { v1: "v1" };
      const ALL = "Tất cả";

      let currentUi = null;

      function loadSpec(url) {
        if (!currentUi) return;
        currentUi.specActions.download(url);
      }

      function specUrl(service, module) {
        if (module && module !== ALL) return CATALOG.modules[module];
        if (service && service !== ALL) return CATALOG.services[service].url;
        return CATALOG.allUrl;
      }

      function populateVersionSelect() {
        const sel = document.getElementById("version-select");
        sel.innerHTML = "";
        Object.keys(API_VERSIONS).forEach((v) => {
          const o = document.createElement("option");
          o.value = v;
          o.textContent = v;
          sel.appendChild(o);
        });
      }

      function populateServiceSelect() {
        const sel = document.getElementById("service-select");
        sel.innerHTML = "";
        [ALL].concat(Object.keys(CATALOG.services)).forEach((name) => {
          const o = document.createElement("option");
          o.value = name;
          o.textContent = name;
          sel.appendChild(o);
        });
        sel.value = ALL;
      }

      function populateModuleSelect() {
        const service = document.getElementById("service-select").value;
        const modules = service === ALL ? Object.keys(CATALOG.modules) : CATALOG.services[service].modules;
        const sel = document.getElementById("module-select");
        sel.innerHTML = "";
        [ALL].concat(modules.slice().sort()).forEach((name) => {
          const o = document.createElement("option");
          o.value = name;
          o.textContent = name;
          sel.appendChild(o);
        });
      }

      function onServiceChange() {
        populateModuleSelect();
        loadSpec(specUrl(document.getElementById("service-select").value, ALL));
      }

      function onModuleChange() {
        loadSpec(
          specUrl(
            document.getElementById("service-select").value,
            document.getElementById("module-select").value,
          ),
        );
      }

      window.onload = function () {
        document.getElementById("service-select").addEventListener("change", onServiceChange);
        document.getElementById("module-select").addEventListener("change", onModuleChange);

        currentUi = SwaggerUIBundle({
          url: CATALOG.allUrl,
          dom_id: "#swagger-ui",
          deepLinking: true,
          presets: [SwaggerUIBundle.presets.apis, SwaggerUIStandalonePreset],
          layout: "StandaloneLayout",
          docExpansion: "none",
        });

        populateVersionSelect();
        populateServiceSelect();
        populateModuleSelect();
      };

      function expandAll() {
        document
          .querySelectorAll(".opblock-tag-section:not(.is-open) .opblock-tag")
          .forEach((btn) => btn.click());
        setTimeout(() => {
          document
            .querySelectorAll('.opblock-summary-control:not([aria-expanded="true"])')
            .forEach((btn) => btn.click());
        }, 100);
      }

      function collapseAll() {
        document
          .querySelectorAll('.opblock-summary-control[aria-expanded="true"]')
          .forEach((btn) => btn.click());
        setTimeout(() => {
          document
            .querySelectorAll(".opblock-tag-section.is-open .opblock-tag")
            .forEach((btn) => btn.click());
        }, 100);
      }
    </script>
  </body>
</html>
`
